//! Teacher-forced full-vocabulary/native-margin audit. Kernel f64 bounds live in
//! the kernel/real-activation checks; a per-kernel tolerance is not a bound on
//! whole-network logits after discontinuous expert top-k routing.
use anyhow::{Result,ensure};use lfm2_engine::{gpu_lfm::GpuEngine,model_file::ModelFile};use serde_json::json;use sha2::{Digest,Sha256};
fn top(v:&[f32])->(usize,f32,f32){let(mut i,mut a,mut b)=(0,f32::NEG_INFINITY,f32::NEG_INFINITY);for(j,&x)in v.iter().enumerate(){if x>a{b=a;a=x;i=j;}else if x>b{b=x;}}(i,a,b)}
fn main()->Result<()> {
 let a:Vec<_>=std::env::args().collect();let m=ModelFile::open(&a[1])?;let raw=std::fs::read_to_string(&a[2])?;let q:serde_json::Value=serde_json::from_str(raw.lines().last().unwrap())?;let ids:Vec<u32>=serde_json::from_value(q["prompt_tokens"].clone())?;let tokens:Vec<u32>=serde_json::from_value(q["tokens"].clone())?;let root=std::path::Path::new(&a[3]);let out=std::path::Path::new(&a[4]);std::fs::create_dir_all(out)?;let mut e=GpuEngine::load(&m)?;e.set_ctx(4096);let mut logits=vec![];let mut pos=0;
 for chunk in ids.chunks(64){logits=e.forward(chunk,pos as i64)?;pos+=chunk.len();}
 let mut steps=vec![];
 for step in 0..=tokens.len(){
  let native=std::fs::read(root.join(format!("{step}.bin")))?;let r:Vec<f32>=native.chunks_exact(4).map(|x|f32::from_le_bytes(x.try_into().unwrap())).collect();ensure!(r.len()==logits.len()&&r.iter().chain(&logits).all(|x|x.is_finite()),"nonfinite/size logits");let nt=top(&r);let ct=top(&logits);let max=logits.iter().zip(&r).map(|(&x,&y)|(x-y).abs()).fold(0f32,f32::max);let diff=logits.iter().zip(&r).map(|(&x,&y)|(x as f64-y as f64).powi(2)).sum::<f64>();let norm=r.iter().map(|&x|(x as f64).powi(2)).sum::<f64>();let rel=(diff/norm.max(1e-30)).sqrt();ensure!(rel.is_finite(),"nonfinite logit error");let bytes=bytemuck::cast_slice::<f32,u8>(&logits);std::fs::write(out.join(format!("{step}.bin")),bytes)?;
  let prior=if let Some(dir)=a.get(5) {let b=std::fs::read(std::path::Path::new(dir).join(format!("{step}.bin")))?;ensure!(b.len()==bytes.len(),"reference logits size");let v:Vec<f32>=b.chunks_exact(4).map(|x|f32::from_le_bytes(x.try_into().unwrap())).collect();ensure!(v.iter().all(|x|x.is_finite()),"nonfinite prior logits");let pe=v.iter().zip(&r).map(|(&x,&y)|(x as f64-y as f64).powi(2)).sum::<f64>();let mismatches=b.chunks_exact(4).zip(bytes.chunks_exact(4)).filter(|(x,y)|x!=y).count();if ids.len()==138 {ensure!(mismatches==0,"short accepted-arithmetic bit mismatch");}json!({"bit_mismatches":mismatches,"prior_relative_l2":(pe/norm.max(1e-30)).sqrt(),"prior_logits_sha256":hex::encode(Sha256::digest(&b))})} else {serde_json::Value::Null};
  steps.push(json!({"step":step,"position":pos,"native_argmax":nt.0,"candidate_argmax":ct.0,"native_margin":nt.1-nt.2,"candidate_margin":ct.1-ct.2,"max_abs_error":max,"relative_l2":rel,"exceeds_per_kernel_tolerance_diagnostic":rel>=1e-3,"uniform_error_margin_proof":2.*max<nt.1-nt.2,"exact_greedy":nt.0==ct.0,"native_logits_sha256":hex::encode(Sha256::digest(&native)),"candidate_logits_sha256":hex::encode(Sha256::digest(bytes)),"prior_accepted_policy":prior}));
  ensure!(nt.0==ct.0,"teacher forced argmax mismatch at {step}");if step<tokens.len(){ensure!(nt.0==tokens[step] as usize,"native trajectory mismatch");logits=e.forward(&[tokens[step]],pos as i64)?;pos+=1;}
 }
 println!("{}",json!({"pass":true,"input_tokens":ids.len(),"output_tokens":tokens.len(),"final_forward_included":true,"finite_full_vocabulary":true,"kernel_numeric_bounds_unchanged":true,"tolerance_scope":"Full-model relative error is reported, not confused with a per-kernel1e-3 f64 bound. Exact greedy at every native teacher-forced position is mandatory. Captured-real reordered-kernel nonregression is checked independently.","steps":steps}));Ok(())
}
